1	// Acceptance test for the change request:
2	//   "The money I am owed should only count invoices I have actually sent. Do not count drafts."
3	//
4	// The dashboard's "money owed" figure (dashboard-outstanding-total) is the sum of the invoices I
5	// have actually SENT and not yet been paid for. An invoice moves through DRAFT -> SENT -> PAID
6	// (see invoice-send.spec). A DRAFT has not been sent, so it is NOT money I am owed and must not be
7	// counted; a PAID invoice has been settled, so it is not owed either. Only SENT invoices count.
8	//
9	// This is a change to how the owed total is computed: before it, an unsent draft would have been
10	// swept into the figure. The assertions below pin the new rule — drafts are excluded — and then
11	// demonstrate it dynamically: SENDING a draft (the only way its money becomes owed) grows the owed
12	// total by exactly that invoice's amount.
13	//
14	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
15	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
16	// `invoices` honours { id, amount, projectId, status }.
17	import { test, expect, type Page, type Locator } from '@playwright/test';
18	import { resetAndSeed } from '../support/seed';
19	
20	// A money figure may be rendered bare (550) or dressed up ("$550.00"). Assert the figure CARRIES
21	// the expected number as a standalone token, so the test binds to the meaning rather than to one
22	// presentation. The surrounding (^|\D)…(\D|$) keeps a smaller number from matching inside a larger
23	// one (550 must not satisfy a check for 50, nor 55 match inside 550).
24	const asToken = (n: number) => new RegExp(`(^|\\D)${n}(\\D|$)`);
25	const shows = (cell: Locator, n: number) => expect(cell).toContainText(asToken(n));
26	const hides = (cell: Locator, n: number) => expect(cell).not.toContainText(asToken(n));
27	
28	const SENT = /\bsent\b/i;
29	
30	const outstanding = (page: Page) => page.getByTestId('dashboard-outstanding-total');
31	
32	// Reach the dashboard the way a user would — follow its nav link from the home screen — rather than
33	// pinning the dashboard's URL.
34	async function openDashboard(page: Page): Promise<void> {
35	  await page.goto('/');
36	  const nav = page.getByTestId('nav-dashboard');
37	  await expect(nav).toBeVisible();
38	  await nav.click();
39	  await expect(page.getByTestId('dashboard-page')).toBeVisible();
40	  await expect(page.getByTestId('dashboard')).toBeVisible();
41	}
42	
43	test.describe('Money owed counts only invoices I have sent, not drafts', () => {
44	  test('a draft is not money owed: only the sent invoices add up to the owed total', async ({
45	    page,
46	  }) => {
47	    // Across the stages: one DRAFT (70) not yet sent, two SENT and awaiting payment (200 + 55 = 255)
48	    // and one PAID (400). Money owed is only the SENT pair — 255. The draft is not owed because it
49	    // has not been sent, and the paid invoice is no longer owed.
50	    await resetAndSeed({
51	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
52	      projects: [
53	        { id: 1, name: 'Website Redesign', clientId: 1 },
54	        { id: 2, name: 'Mobile App', clientId: 1 },
55	      ],
56	      invoices: [
57	        { id: 1, amount: 70, projectId: 1, status: 'DRAFT' },
58	        { id: 2, amount: 200, projectId: 1, status: 'SENT' },
59	        { id: 3, amount: 55, projectId: 2, status: 'SENT' },
60	        { id: 4, amount: 400, projectId: 2, status: 'PAID' },
61	      ],
62	    });
63	
64	    await openDashboard(page);
65	
66	    // Owed is the two SENT invoices: 200 + 55 = 255.
67	    await shows(outstanding(page), 255);
68	    // The unsent draft (70) is NOT counted — this is the heart of the change.
69	    await hides(outstanding(page), 70);
70	    // Nor is the paid invoice (400), nor everything ever invoiced (725).
71	    await hides(outstanding(page), 400);
72	    await hides(outstanding(page), 725);
73	    // And it is not "everything not yet paid" (draft + sent = 325): a draft is excluded even though
74	    // it is unpaid. Nor "everything not a draft" (sent + paid = 655).
75	    await hides(outstanding(page), 325);
76	    await hides(outstanding(page), 655);
77	  });
78	
79	  test('with only drafts seeded, nothing is owed — no invoice has been sent', async ({ page }) => {
80	    // Money has been invoiced, but every invoice is still a DRAFT: none has been sent, so nothing is
81	    // owed. (Previously an unpaid draft would have been counted; now it is not.)
82	    await resetAndSeed({
83	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
84	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
85	      invoices: [
86	        { id: 1, amount: 300, projectId: 1, status: 'DRAFT' },
87	        { id: 2, amount: 450, projectId: 1, status: 'DRAFT' },
88	      ],
89	    });
90	
91	    await openDashboard(page);
92	
93	    // Nothing has been sent, so nothing is owed.
94	    await shows(outstanding(page), 0);
95	    await hides(outstanding(page), 300);
96	    await hides(outstanding(page), 450);
97	    await hides(outstanding(page), 750);
98	  });
99	
100	  test('sending a draft is what makes its money owed — the owed total grows by that amount', async ({
101	    page,
102	  }) => {
103	    // A single DRAFT invoice for 140, not yet sent.
104	    await resetAndSeed({
105	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
106	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
107	      invoices: [{ id: 1, amount: 140, projectId: 1, status: 'DRAFT' }],
108	    });
109	
110	    // While it is a draft, it is not money owed.
111	    await openDashboard(page);
112	    await shows(outstanding(page), 0);
113	    await hides(outstanding(page), 140);
114	
115	    // Send the invoice — the only way a draft becomes money I am owed.
116	    await page.goto('/projects/1');
117	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
118	    const send = page.getByTestId('invoice-send-1');
119	    await expect(send).toBeVisible();
120	    await send.click();
121	    await expect(
122	      page.getByTestId('invoice-row-1').getByTestId('invoice-status'),
123	    ).toHaveText(SENT);
124	
125	    // Back on the dashboard the figure now counts it: the owed total is 140.
126	    await openDashboard(page);
127	    await shows(outstanding(page), 140);
128	  });
129	});
130

